import { currentUser, currentSessionTokenHash, destroySession } from "@/lib/auth";
import { verifyAssertion, publicKeyFor } from "@/lib/cyrus/bridge/assertion";
import { bridgeGate, claimOnce, go, limited, notFound } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/**
 * Front-channel leg of a cyrus.my sign-out. cyrus.my already revoked the Nxeon session row (shared database), so the
 * Nxeon cookie is dead; this clears it in the browser. Requires Cyrus' signed, single-use logout assertion for THIS
 * session (sid) or account, so a third-party link cannot sign anyone out. Always lands on the fixed Cyrus page.
 */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "nxeon");
  if (!cfg) return notFound();
  const back = go(`${cfg.cyrusOrigin}/sign-in?signed_out=1`);
  if (limited(req, "logout")) return back;
  const t = new URL(req.url).searchParams.get("t");
  const v = verifyAssertion(t, { key: publicKeyFor("cyrus"), iss: cfg.cyrusOrigin, aud: cfg.nxeonOrigin, typ: "logout", nonce: null, claimOnce });
  if (!v.ok) return back;
  const sid = await currentSessionTokenHash();
  const user = await currentUser();
  if ((sid && v.claims.sid && sid === v.claims.sid) || (!user && sid) || user?.id === v.claims.sub) await destroySession();
  return go(`${cfg.cyrusOrigin}/sign-in?signed_out=1`);
}
