import { safeNext } from "@/lib/safe-next";
import { callbackUrls } from "@/lib/cyrus/bridge/config";
import { authorizeQuery } from "@/lib/cyrus/bridge/flow";
import { beginHandshake, bridgeGate, go, limited, notFound } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/** "Sign in with Cyrus" on nxeon.cloud: state + nonce here, then cyrus.my vouches for its (Nxeon-derived) session. */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "nxeon");
  if (!cfg) return notFound();
  if (limited(req, "start")) return go(`${cfg.nxeonOrigin}/login?error=cyrus_ratelimited`);
  const next = safeNext(new URL(req.url).searchParams.get("next")) ?? "/dashboard";
  const st = await beginHandshake("nxeon", next);
  return go(`${cfg.cyrusOrigin}/auth/handoff?${authorizeQuery({ clientId: "nxeon", redirectUri: callbackUrls(cfg).nxeon, state: st.s, nonce: st.n, prompt: "login" })}`);
}
