cat > app/sso/cyrus/return/route.ts <<'EOF'
import { db } from "@/lib/db";
import { createSession } from "@/lib/auth";
import { emailVerificationError } from "@/lib/email-verification";
import { recordRequestActivity } from "@/lib/activity-request";
import { safeNext } from "@/lib/safe-next";
import { safeEqual, verifyAssertion, publicKeyFor } from "@/lib/cyrus/bridge/assertion";
import { bridgeGate, claimOnce, go, limited, notFound, takeHandshake } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/**
 * "Sign in with Cyrus" return leg on nxeon.cloud. Checks our state cookie, then Cyrus' assertion (signature, exact
 * iss/aud, our nonce, single use), matches the account by id ONLY, and issues the same Nxeon session a password
 * login issues. Customer accounts only, verified email, no 2FA accounts (those use the password + code path).
 */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "nxeon");
  if (!cfg) return notFound();
  const fail = (code: string) => go(`${cfg.nxeonOrigin}/login?error=cyrus_${code}`);
  if (limited(req, "return")) return fail("ratelimited");
  const url = new URL(req.url);
  const st = await takeHandshake("nxeon");
  const state = url.searchParams.get("state") ?? "";
  if (!st || !state || !safeEqual(st.s, state)) return fail("state");
  if (url.searchParams.get("error")) return fail("cancelled");
  const v = verifyAssertion(url.searchParams.get("code"), { key: publicKeyFor("cyrus"), iss: cfg.cyrusOrigin, aud: cfg.nxeonOrigin, typ: "login", nonce: st.n, claimOnce });
  if (!v.ok) return fail("assertion");
  const user = await db.user.findUnique({ where: { id: v.claims.sub } });
  if (!user || user.suspended) return fail("account");
  if (user.role !== "CUSTOMER" || user.totpEnabled) return fail("staff");
  if (await emailVerificationError(user)) return fail("unverified");
  await db.auditLog.create({ data: { userId: user.id, action: "user.login", detail: "Cyrus" } }).catch(() => {});
  await recordRequestActivity({ type: "auth.login", userId: user.id, label: "Signed in with Cyrus", data: { method: "cyrus" } }, { headers: req.headers });
  await createSession(user.id);
  return go(`${cfg.nxeonOrigin}${safeNext(st.next) ?? "/dashboard"}`);
}
