// Cyrus one-account bridge: assertion + handshake rules (no network, no DB).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { generateKeyPairSync } from "node:crypto";
import { mintAssertion, verifyAssertion, privateKeyFor, publicKeyFor, seal, unseal, randomToken } from "../lib/cyrus/bridge/assertion";
import { parseAuthorize, authorizeQuery, callbackUrl, bridgeErrorText } from "../lib/cyrus/bridge/flow";
import { bridgeConfig } from "../lib/cyrus/bridge/config";

const env = { AUTH_SECRET: "test-secret-0123456789abcdef", CYRUS_DOMAIN_MODE: "1", APP_URL: "https://nxeon.cloud" };
const cfg = bridgeConfig(env);
const once = () => { const seen = new Set<string>(); return (k: string) => (seen.has(k) ? false : (seen.add(k), true)); };
const nonce = randomToken(24);
const base = { typ: "login" as const, iss: "https://nxeon.cloud", aud: "https://cyrus.my", sub: "cuser_123456", nonce, sid: "abc" };
const check = (raw: string, o: Partial<Parameters<typeof verifyAssertion>[1]> = {}) =>
  verifyAssertion(raw, { key: publicKeyFor("nxeon", env), iss: base.iss, aud: base.aud, typ: "login", nonce, claimOnce: once(), ...o });

describe("identity assertions", () => {
  const good = mintAssertion(base, privateKeyFor("nxeon", env));
  it("verifies and carries the stable id + parent session", () => {
    const r = check(good);
    assert.ok(r.ok);
    if (r.ok) { assert.equal(r.claims.sub, "cuser_123456"); assert.equal(r.claims.sid, "abc"); }
  });
  it("is single use", () => {
    const c = once();
    assert.ok(check(good, { claimOnce: c }).ok);
    assert.deepEqual(check(good, { claimOnce: c }), { ok: false, reason: "replay" });
  });
  it("rejects the wrong party, type, nonce, signer, tampering and age", () => {
    assert.equal((check(good, { aud: "https://evil.test" }) as { reason: string }).reason, "wrong_party");
    assert.equal((check(good, { iss: "https://cyrus.my" }) as { reason: string }).reason, "wrong_party");
    assert.equal((check(good, { typ: "logout" }) as { reason: string }).reason, "wrong_party");
    assert.equal((check(good, { nonce: randomToken(24) }) as { reason: string }).reason, "nonce");
    assert.equal((check(good, { key: publicKeyFor("cyrus", env) }) as { reason: string }).reason, "bad_signature");
    const [b, s] = good.split(".");
    const forged = Buffer.from(JSON.stringify({ ...JSON.parse(Buffer.from(b, "base64url").toString()), sub: "cadmin_999999" })).toString("base64url");
    assert.equal((check(`${forged}.${s}`) as { reason: string }).reason, "bad_signature");
    const old = mintAssertion({ ...base, nowMs: Date.now() - 10 * 60_000 }, privateKeyFor("nxeon", env));
    assert.equal((check(old) as { reason: string }).reason, "expired");
    assert.equal((check("garbage") as { reason: string }).reason, "malformed");
  });
  it("derived keys depend on the secret; PEM env overrides them (move day)", () => {
    assert.equal(check(mintAssertion(base, privateKeyFor("nxeon", { AUTH_SECRET: "another-secret-0123456789" }))).ok, false);
    const kp = generateKeyPairSync("ed25519");
    const e2 = { ...env, CYRUS_BRIDGE_NXEON_PRIVATE_KEY: kp.privateKey.export({ type: "pkcs8", format: "pem" }).toString(), CYRUS_BRIDGE_NXEON_PUBLIC_KEY: kp.publicKey.export({ type: "spki", format: "pem" }).toString() };
    const t = mintAssertion(base, privateKeyFor("nxeon", e2));
    assert.ok(check(t, { key: publicKeyFor("nxeon", e2) }).ok);
    assert.equal(check(t).ok, false);
  });
  it("refuses to run without a secret", () => assert.throws(() => privateKeyFor("nxeon", {})));
});

describe("sealed cookies", () => {
  it("round-trips, and rejects tampering, another purpose and expiry", () => {
    const c = seal("state:cyrus", { s: "x", n: "y", next: "/studio" }, 600, env);
    assert.equal(unseal<{ s: string }>("state:cyrus", c, env)?.s, "x");
    assert.equal(unseal("state:nxeon", c, env), null);
    assert.equal(unseal("state:cyrus", c.slice(0, -2) + "AA", env), null);
    assert.equal(unseal("state:cyrus", c, env, Date.now() + 601_000), null);
  });
});

describe("authorize parameters", () => {
  const q = (o: Record<string, string>) => new URLSearchParams(o);
  const ok = { client_id: "cyrus", redirect_uri: "https://cyrus.my/auth/nxeon/callback", state: randomToken(24), nonce };
  it("accepts only the exact client + callback", () => {
    assert.ok(parseAuthorize(q(ok), "cyrus", cfg));
    for (const bad of [
      { ...ok, client_id: "kodely" },
      { ...ok, redirect_uri: "https://cyrus.my/auth/nxeon/callback/../x" },
      { ...ok, redirect_uri: "https://cyrus.my.evil.test/auth/nxeon/callback" },
      { ...ok, redirect_uri: "https://cyrus.my/auth/nxeon/callback?x=1" },
      { ...ok, state: "short" },
      { ...ok, nonce: "" },
    ]) assert.equal(parseAuthorize(q(bad), "cyrus", cfg), null, JSON.stringify(bad));
    assert.equal(parseAuthorize(q(ok), "nxeon", cfg), null);
    assert.ok(parseAuthorize(q({ ...ok, client_id: "nxeon", redirect_uri: "https://nxeon.cloud/sso/cyrus/return" }), "nxeon", cfg));
  });
  it("round-trips the query and builds the callback with state", () => {
    const p = parseAuthorize(q({ ...ok, prompt: "create" }), "cyrus", cfg)!;
    assert.equal(p.prompt, "create");
    assert.deepEqual(parseAuthorize(new URLSearchParams(authorizeQuery(p)), "cyrus", cfg), p);
    const u = new URL(callbackUrl(p, { error: "access_denied" }));
    assert.equal(u.origin + u.pathname, ok.redirect_uri);
    assert.equal(u.searchParams.get("state"), ok.state);
  });
  it("only fixed error copy", () => {
    assert.equal(bridgeErrorText("<script>"), null);
    assert.equal(bridgeErrorText("toString"), null);
    assert.ok(bridgeErrorText("state"));
  });
});
