import { NextResponse } from "next/server";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { checkRateLimit } from "@/lib/rate-limit";
import { isPlanTier } from "@/lib/cyrus/tokens/config";
import { tokensActiveFor } from "@/lib/cyrus/tokens/access";
import { openPlanCheckout, openTopupCheckout } from "@/lib/cyrus/tokens/billing";
import { NOT_FOUND } from "@/app/api/mod-builder/_lib";

export const dynamic = "force-dynamic";

/** Open a Stripe Checkout (custom "elements" UI) for a Cyrus plan or a one-off top-up. */
export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user || !(await tokensActiveFor(user))) return NOT_FOUND();
  const rl = checkRateLimit(`cyrus:checkout:${user.id}`, { max: 6, windowMs: 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many tries. Wait ${rl.retryAfterSec}s.` }, { status: 429 });
  const body = (await req.json().catch(() => ({}))) as { kind?: string; tier?: unknown; cents?: unknown };
  try {
    const r = body.kind === "plan" && isPlanTier(body.tier) ? await openPlanCheckout(user, body.tier)
      : body.kind === "topup" ? await openTopupCheckout(user, Math.round(Number(body.cents)))
      : { ok: false as const, error: "Pick a plan or an amount." };
    return r.ok ? NextResponse.json({ clientSecret: r.clientSecret, publishableKey: r.publishableKey }) : NextResponse.json({ error: r.error }, { status: 400 });
  } catch (e) {
    console.error("[cyrus-tokens] checkout", user.id, (e as Error).message);
    return NextResponse.json({ error: "We couldn't open checkout. Nothing was charged." }, { status: 502 });
  }
}
