// ---------------------------------------------------------------------------
// Credits
// ---------------------------------------------------------------------------

export type CreditInput = {
  userId: string;
  amount: number;
  kind: "grant" | "purchase" | "refund";
  source: LotSource;
  sourceRef?: string | null;
  idemKey: string;
  expiresAt?: Date | null;
  note?: string | null;
  meta?: Prisma.InputJsonValue;
  actorId?: string | null;
  now?: Date;
  /** Runs under the account lock before crediting: cap the amount (abuse limits). */
  clamp?: (tx: Tx, amount: number, now: Date) => Promise<{ amount: number; note?: string }>;
};

export type CreditResult = { created: boolean; amount: number; lotId: string | null; note?: string | null };

/** Add tokens (a new lot). Idempotent on idemKey; a zero amount still writes the row (so a capped grant is final). */
export async function creditTokens(i: CreditInput): Promise<CreditResult> {
  const now = i.now ?? new Date();
  const r = await run(i.userId, async (tx) => {
    if (await exists(tx, i.idemKey)) throw new Duplicate();
    await expireDue(tx, i.userId, now);
    let amount = Math.max(0, Math.floor(i.amount));
    let note = i.note ?? null;
    if (i.clamp) {
      const c = await i.clamp(tx, amount, now);
      if (c.amount < amount) note = [note, c.note].filter(Boolean).join("; ") || null;
      amount = Math.max(0, Math.floor(c.amount));
    }
    let lotId: string | null = null;
    if (amount > 0) {
      const lot = await tx.cyrusTokenLot.create({ data: { userId: i.userId, source: i.source, sourceRef: i.sourceRef ?? null, amount, remaining: amount, expiresAt: i.expiresAt ?? null } });
      lotId = lot.id;
    }
    const after = await store(tx, i.userId, amount > 0 ? { lifetimeGranted: { increment: amount } } : {});
    await writeLedger(tx, i.userId, { kind: i.kind, delta: amount, idemKey: i.idemKey, source: i.source, sourceRef: i.sourceRef ?? null, lotId, note, meta: i.meta, actorId: i.actorId ?? null }, after);
    return { created: true, amount, lotId, note };
  });
  if (r === DUP) {
    const prev = await db.cyrusTokenLedger.findUnique({ where: { idemKey: i.idemKey } });
    return { created: false, amount: prev?.delta ?? 0, lotId: prev?.lotId ?? null, note: prev?.note };
  }
  return r;
}

// ---------------------------------------------------------------------------
// Builds: reserve -> settle / release
// ---------------------------------------------------------------------------

export async function handleRefundedCharge(ch: Stripe.Charge): Promise<number> {
  const pi = idOf(ch.payment_intent as string | { id: string } | null);
  if (!pi || !ch.amount || !ch.amount_refunded) return 0;
  const rows = await db.cyrusTokenLedger.findMany({ where: { kind: "purchase", meta: { path: ["paymentIntent"], equals: pi } } });
  let total = 0;
  for (const row of rows) {
    if (!row.lotId || row.delta <= 0) continue;
    const want = Math.round(row.delta * Math.min(1, ch.amount_refunded / ch.amount));
    const prior = await db.cyrusTokenLedger.findMany({ where: { kind: "revoke", sourceRef: row.id } });
    const already = prior.reduce((a, x) => a + ((x.meta as { requested?: number } | null)?.requested ?? 0), 0);
    if (want - already <= 0) continue;
    const r = await revokeTokens({ userId: row.userId, amount: want - already, lotIds: [row.lotId], sourceRef: row.id, idemKey: `refund:${ch.id}:${ch.amount_refunded}:${row.id}`, note: `Refund ${ch.id}`, meta: { charge: ch.id, refunded: ch.amount_refunded } });
    if (r.created) total += r.revoked;
  }
  return total;
}

// ---------------------------------------------------------------------------
// Webhook entry
// ---------------------------------------------------------------------------

/**
 * Called by app/api/stripe/webhook for EVERY verified event. Returns true when the event
 * was a Cyrus one. Re-fetches the object from Stripe before acting (the event body is a
 * hint, not the truth), so a replayed or out-of-order event applies the current state.
 */
export async function handleCyrusStripeEvent(event: Stripe.Event): Promise<boolean> {

// NXEON SIDE: the receiver for Cyrus webhooks (Cyrus -> Nxeon). Framework-free (Request -> Response); a later Nxeon
// route (e.g. app/api/webhooks/cyrus/route.ts) wraps it. NOTHING mounts it today. Imports nothing from lib/cyrus.
// Checks, in order: body size -> headers present -> timestamp within 300 s -> HMAC-SHA256 signature (several "v1=" values
// allowed during a secret rotation, constant-time) -> exactly-once by event id (24 h) -> JSON envelope -> the handler.
// 2xx tells Cyrus "done"; a handler throw answers 500 so Cyrus retries (the id is released so the retry is processed).
import { createHmac, timingSafeEqual } from "node:crypto";

export const CYRUS_WEBHOOK_EVENTS = ["build.finished", "mod.published", "install.result", "delivery.rolledback", "library.contributed"] as const;
export type CyrusWebhookType = (typeof CYRUS_WEBHOOK_EVENTS)[number];
export type CyrusWebhook = { id: string; type: CyrusWebhookType; createdAt: string; subject: string | null; data: Record<string, unknown> };

