export const RECEIVER_MAX_BODY = 256 * 1024;

/** Remembers processed ids (memory here; the CyrusWebhookReceipt table for several instances). */
export interface ReceiptStore {
  /** true when newly recorded; false when already seen */
  claim(id: string, type: string, nowMs: number): Promise<boolean>;
  release(id: string): Promise<void>;
}
