// Cyrus purchases through the payment provider (Nxeon: one Stripe + one wallet), started on either host.
// HOST SEAM: wallet + event delivery come from host.billing; no Nxeon imports.
//
//   applyPurchaseEvent  THE credit/reverse step for a purchase, keyed by the SAME idemKey the direct path uses, so the
//                       direct call, the signed webhook (Cyrus apart), a redelivery and the reconcile sweep can all
//                       run it and tokens land exactly once. purchase.refunded takes back unspent tokens of that lot.
//   deliverPurchase     direct (one app, default) or, with CYRUS_PURCHASE_EVENTS=1 and host.billing.emitPurchase,
//                       the signed webhook/outbox path -> state "pending" until the receiver applies it.
//   payTopupWithWallet  wallet top-up saga (flag CYRUS_WALLET_PAY): idempotent wallet charge (reference) -> deliver
//                       -> on a failed credit, compensating refund; a lost step is found by reconcileWalletTopups.
import { cyrusDb as db } from "../db";
import { getHost } from "../host";
import type { PurchaseEnvelope } from "../host/types";
import { loadTokenConfig } from "./config";
import { topupTokens, validTopupCents, fmt } from "./economy";
import { creditTokens, revokeTokens } from "./ledger";

const DAY = 86_400_000;
const locks = new Set<string>();
export const walletPayEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_WALLET_PAY === "1";
export const purchaseEventsEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_PURCHASE_EVENTS === "1";

export function purchaseEnvelope(type: PurchaseEnvelope["type"], subject: string, data: PurchaseEnvelope["data"], now = new Date()): PurchaseEnvelope {
  return { id: `pe_${data.idemKey}${type === "purchase.refunded" ? `:r${data.refundedCents ?? 0}` : ""}`.slice(0, 160), type, createdAt: now.toISOString(), subject, data };
}

export type ApplyResult = { applied: boolean; tokens: number };

/** Idempotent. Completed -> a token lot; refunded -> unspent tokens of that lot back (pro rata to the refund). */
export async function applyPurchaseEvent(e: PurchaseEnvelope): Promise<ApplyResult> {
  const d = e.data;
  if (!/^[A-Za-z0-9:_-]{6,160}$/.test(d.idemKey) || !e.subject) throw new Error("invalid purchase event");
  if (e.type === "purchase.completed") {
    const r = await creditTokens({
      userId: e.subject, amount: d.tokens, kind: "purchase", source: "topup", sourceRef: d.idemKey, idemKey: d.idemKey,
      expiresAt: d.expiresAt ? new Date(d.expiresAt) : null, note: d.note, meta: { paidCents: d.cents, method: d.method, event: e.id },
    });
    return { applied: r.created, tokens: r.created ? r.amount : 0 };
  }
  const row = await db.cyrusTokenLedger.findUnique({ where: { idemKey: d.idemKey } });
  if (!row?.lotId || row.delta <= 0 || row.userId !== e.subject || !d.cents) return { applied: false, tokens: 0 };
  const want = Math.round(row.delta * Math.min(1, (d.refundedCents ?? 0) / d.cents));
  const r = await revokeTokens({ userId: row.userId, amount: want, lotIds: [row.lotId], sourceRef: row.id, idemKey: `refund:${d.idemKey}:${d.refundedCents ?? 0}`, note: `Refund ${d.idemKey}`, meta: { refundedCents: d.refundedCents ?? 0 } });
  return { applied: r.created, tokens: r.revoked };
}

/** Direct credit (one app) or the signed webhook path (Cyrus apart). */
export async function deliverPurchase(e: PurchaseEnvelope): Promise<{ state: "credited" | "pending"; tokens: number }> {
  const emit = getHost().billing.emitPurchase;
  if (purchaseEventsEnabled() && emit) {
    await emit(e);
    return { state: "pending", tokens: 0 };
  }
  const r = await applyPurchaseEvent(e);
  return { state: "credited", tokens: r.tokens };
}

export type WalletPayState = "credited" | "pending" | "insufficient_funds" | "failed" | "unavailable" | "in_progress" | "invalid";
export const walletRef = (userId: string, key: string) => `cwt:${userId}:${key}`;

/** Status of a wallet top-up by its key: honest, from the ledger and the wallet itself. */
export async function walletTopupStatus(userId: string, key: string): Promise<WalletPayState> {
  const ref = walletRef(userId, key);
  if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: ref }, select: { id: true } })) return "credited";
  const w = getHost().billing.wallet;
  const moves = (await w?.findByReference?.({ userId, prefix: ref, sinceMs: Date.now() - 30 * DAY })) ?? [];
  const charged = moves.some((m) => m.reference === ref && m.cents < 0);
  const refunded = moves.some((m) => m.reference === `${ref}:refund` && m.cents > 0);
  return refunded ? "failed" : charged ? "pending" : "invalid";
}

export async function payTopupWithWallet(user: { id: string }, cents: number, key: string): Promise<{ state: WalletPayState; tokens: number; error?: string }> {
  const wallet = getHost().billing.wallet;
  if (!walletPayEnabled() || !wallet) return { state: "unavailable", tokens: 0, error: "Paying with your wallet isn't available right now." };
  if (!/^[A-Za-z0-9_-]{16,64}$/.test(key)) return { state: "invalid", tokens: 0, error: "Missing purchase key." };
  const cfg = await loadTokenConfig();
  if (!cfg.topup.enabled) return { state: "unavailable", tokens: 0, error: "Top-ups aren't available right now." };
  if (!validTopupCents(cents, cfg)) return { state: "invalid", tokens: 0, error: `Pick an amount from $${(cfg.topup.minCents / 100).toFixed(0)} to $${(cfg.topup.maxCents / 100).toFixed(0)}.` };
  if (cfg.topup.requiresPaid) {
    const paid = (await getHost().servers.paidCount(user.id)) + (await db.cyrusPlan.count({ where: { userId: user.id } }));
    if (!paid) return { state: "invalid", tokens: 0, error: "Top-ups are for customers with a game server or a Cyrus plan." };
  }
  const ref = walletRef(user.id, key);
  if (locks.has(ref)) return { state: "in_progress", tokens: 0 };
  locks.add(ref);
  try {
    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: ref }, select: { id: true } })) return { state: "credited", tokens: 0 };
    const tokens = topupTokens(cents, cfg);
    const charge = await wallet.charge({ userId: user.id, cents, description: `Cyrus tokens: ${fmt(tokens)}`, reference: ref });
    if (!charge.ok) return { state: charge.error === "insufficient_funds" ? "insufficient_funds" : "invalid", tokens: 0, error: charge.error === "insufficient_funds" ? "Not enough in your wallet. Add funds or pay by card." : "Couldn't charge your wallet." };
    const e = purchaseEnvelope("purchase.completed", user.id, {
      idemKey: ref, kind: "topup", method: "wallet", tokens, cents,
      expiresAt: new Date(Date.now() + cfg.topup.expiryDays * DAY).toISOString(), note: `Top-up $${(cents / 100).toFixed(2)} (wallet)`,
    });
    try {
      const r = await deliverPurchase(e);
      return { state: r.state, tokens: r.tokens };
    } catch (err) {
      console.error("[cyrus-purchase] credit failed after wallet charge", ref, (err as Error).message);
      // Compensate: the money goes back, the purchase is honestly failed. If the refund fails too, the charge stays
      // "pending" and reconcileWalletTopups credits it later.
      try {
        await wallet.refund({ userId: user.id, cents, description: "Refund: Cyrus tokens not credited", reference: `${ref}:refund` });
        return { state: "failed", tokens: 0, error: "We couldn't add your tokens, so your wallet was refunded." };
      } catch {
        return { state: "pending", tokens: 0, error: "Your tokens are on the way. If they don't appear in a few minutes, contact support." };
      }
    }
  } finally {
    locks.delete(ref);
  }
}

/** Reconciliation: any referenced wallet charge without a ledger row (and without a refund) is credited. */
export async function reconcileWalletTopups(o: { userId?: string; sinceMs?: number } = {}): Promise<{ checked: number; credited: number }> {
  const w = getHost().billing.wallet;
