export async function maybeReconcileUser(userId: string, maxAgeMs = 5 * 60_000): Promise<void> {
  if (!configured()) return;
  const p = await db.cyrusPlan.findUnique({ where: { userId } });
  if (!p || (p.lastSyncAt && Date.now() - p.lastSyncAt.getTime() < maxAgeMs)) return;
  if (p.endedAt && p.lastSyncAt && p.lastSyncAt > p.endedAt) return;
  try { await reconcileSubscription(p.stripeSubscriptionId); } catch (e) { console.error("[cyrus-tokens] reconcile failed", userId, (e as Error).message); }
