// The outbox here is memory (one instance); the Postgres outbox is the SQL proposal in prisma/manual-migration-cyrus-api-v1.sql.
import { createHmac } from "node:crypto";

export type PurchaseEvent = { id: string; type: "purchase.completed" | "purchase.refunded"; createdAt: string; subject: string; data: Record<string, unknown> };
export type PurchaseTarget = { url: string; secret: string };
export const PURCHASE_RETRY_MS = [60_000, 5 * 60_000, 30 * 60_000, 2 * 3600_000, 12 * 3600_000] as const;

export function purchaseTarget(env: Record<string, string | undefined> = process.env): PurchaseTarget | null {
  const url = env.CYRUS_PURCHASE_EVENTS_URL ?? "", secret = env.CYRUS_PURCHASE_EVENTS_SECRET ?? "";
  if (env.CYRUS_PURCHASE_EVENTS !== "1" || !/^https?:\/\//.test(url) || secret.length < 32 || secret === env.AUTH_SECRET) return null;
  return { url, secret };
}
export const signPurchaseEvent = (secret: string, id: string, ts: string, body: string) => `v1=${createHmac("sha256", secret).update(`${id}.${ts}.${body}`).digest("hex")}`;

type Row = { e: PurchaseEvent; attempts: number; next: number; status: "pending" | "sent" | "dead"; lastError: string | null };

export function createPurchaseSender(o: { target: PurchaseTarget; fetch?: typeof fetch; now?: () => number }) {
  const rows = new Map<string, Row>();
  const now = o.now ?? Date.now;
  const f = o.fetch ?? fetch;
  async function attempt(r: Row): Promise<void> {
    const body = JSON.stringify(r.e), ts = String(Math.floor(now() / 1000));
    try {
