import { NextResponse } from "next/server";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { assertNotImpersonating } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { tokensActiveFor } from "@/lib/cyrus/tokens/access";
import { payTopupWithWallet, walletPayEnabled, walletTopupStatus } from "@/lib/cyrus/tokens/purchase";
import { NOT_FOUND } from "@/app/api/mod-builder/_lib";

export const dynamic = "force-dynamic";
const KEY_RE = /^[A-Za-z0-9_-]{16,64}$/;

/** Buy tokens from the Nxeon wallet (CYRUS_WALLET_PAY), on either host. Idempotency-Key header required. */
export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!walletPayEnabled() || !user || !(await tokensActiveFor(user))) return NOT_FOUND();
  try { await assertNotImpersonating(); } catch (e) { return NextResponse.json({ error: (e as Error).message }, { status: 403 }); }
  if (!checkRateLimit(`cyrus:walletpay:${user.id}`, { max: 6, windowMs: 60_000 }).ok) return NextResponse.json({ error: "Too many tries." }, { status: 429 });
  const key = req.headers.get("idempotency-key") ?? "";
  if (!KEY_RE.test(key)) return NextResponse.json({ error: "Missing purchase key." }, { status: 400 });
  const body = (await req.json().catch(() => ({}))) as { cents?: unknown };
  const r = await payTopupWithWallet(user, Math.round(Number(body.cents)), key);
  const status = r.state === "credited" || r.state === "pending" ? 200 : r.state === "in_progress" ? 409 : r.state === "insufficient_funds" ? 402 : r.state === "failed" ? 502 : 400;
  return NextResponse.json(r, { status });
}

/** Honest status of a wallet purchase by its key: credited / pending / failed / invalid. */
export async function GET(req: Request) {
  const user = await modBuilderUser();
  if (!walletPayEnabled() || !user) return NOT_FOUND();
  const key = new URL(req.url).searchParams.get("key") ?? "";
  if (!KEY_RE.test(key)) return NextResponse.json({ error: "Missing purchase key." }, { status: 400 });
  return NextResponse.json({ state: await walletTopupStatus(user.id, key) });
}
