// Two-origin e2e fixtures for the Cyrus bridge. REFUSES anything but a devhost throwaway database (127.0.0.1:5433/wt_*).
//   seed            -> JSON { userId, adminId, nxeonSession, adminSession, adminImp } (cookie values signed with AUTH_SECRET)
//   revoke <hash>   -> revoke one UserSession row (simulates "Revoke" / sign-out on Nxeon: the back-channel)
//   state <userId>  -> JSON { balanceCents, tokens, sessions:[{hash, revoked}] }
//   cleanup         -> delete the e2e users
import { createHash } from "node:crypto";
import { SignJWT } from "jose";
import { db } from "../../lib/db";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?|$)/.test(url)) { console.error("refusing: not a devhost throwaway DB"); process.exit(2); }
const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
const hash = (t: string) => createHash("sha256").update(t).digest("hex");
const jwt = (claims: Record<string, unknown>, exp: string) => new SignJWT(claims).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime(exp).sign(secret);

async function main() {
  const [cmd, arg] = process.argv.slice(2);
  if (cmd === "seed") {
    for (const [key, value] of [["cyrus_studio_public_enabled", "true"], ["cyrus_tok_live", "true"]]) await db.setting.upsert({ where: { key }, create: { key, value }, update: { value } });
    const tag = Date.now().toString(36);
    const user = await db.user.create({ data: { email: `e2e-bridge-${tag}@example.test`, passwordHash: "x", name: "Bridge E2E", balanceCents: 2000, emailVerifiedAt: new Date() } });
    const admin = await db.user.create({ data: { email: `e2e-bridge-admin-${tag}@example.test`, passwordHash: "x", name: "Bridge Admin", role: "ADMIN", emailVerifiedAt: new Date() } });
    const nxeonSession = await jwt({ sub: user.id, sv: 0, typ: "session" }, "1d");
    const adminSession = await jwt({ sub: admin.id, sv: 0, typ: "session" }, "1d");
    await db.userSession.create({ data: { userId: user.id, tokenHash: hash(nxeonSession) } });
    await db.userSession.create({ data: { userId: admin.id, tokenHash: hash(adminSession) } });
    const adminImp = await jwt({ sub: user.id, adminId: admin.id, typ: "imp" }, "2h");
    console.log(JSON.stringify({ userId: user.id, adminId: admin.id, nxeonSession, nxeonHash: hash(nxeonSession), adminSession, adminImp }));
  } else if (cmd === "revoke") {
    await db.userSession.updateMany({ where: { tokenHash: arg }, data: { revokedAt: new Date() } });
  } else if (cmd === "state") {
    const u = await db.user.findUniqueOrThrow({ where: { id: arg }, select: { balanceCents: true } });
    const lots = await db.cyrusTokenLot.findMany({ where: { userId: arg }, select: { remaining: true } });
    const sessions = await db.userSession.findMany({ where: { userId: arg }, select: { tokenHash: true, revokedAt: true, userAgent: true } });
    console.log(JSON.stringify({ balanceCents: u.balanceCents, tokens: lots.reduce((a, l) => a + l.remaining, 0), sessions: sessions.map((s) => ({ hash: s.tokenHash, revoked: !!s.revokedAt })) }));
  } else if (cmd === "cleanup") {
    const ids = (await db.user.findMany({ where: { email: { startsWith: "e2e-bridge-" } }, select: { id: true } })).map((u) => u.id);
    for (const m of ["cyrusTokenLedger", "cyrusTokenLot", "cyrusTokenAccount", "walletTransaction", "userSession", "auditLog", "activityEvent"] as const) {
      await (db as unknown as Record<string, { deleteMany: (a: unknown) => Promise<unknown> }>)[m]?.deleteMany({ where: { userId: { in: ids } } }).catch(() => {});
    }
    await db.user.deleteMany({ where: { id: { in: ids } } }).catch((e) => console.error("cleanup users:", (e as Error).message));
  }
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });
EOF
